protocol Shareable {
    var shareText: String { get }
}
extension Shareable {
    func share() { UIPasteboard.general.string = shareText }   // free for every conformer
}

struct Article: Shareable, Identifiable, Codable {
    let id: UUID
    let title: String
    var shareText: String { "Read: \(title)" }
}

protocol FeedAPI { func fetch() async throws -> [Article] }    // test seam
struct FakeFeedAPI: FeedAPI { func fetch() async throws -> [Article] { [] } }
